package com.portfolio.features.skill.repository; import com.portfolio.features.skill.entity.Skill; import java.util.*; import org.springframework.data.jpa.repository.*; public interface SkillRepository extends JpaRepository<Skill,UUID>{List<Skill> findByPortfolioIdOrderBySortOrderAscNameAsc(UUID id); boolean existsByPortfolioId(UUID id); @Query("select count(s)>0 from Skill s where s.portfolio.id=:portfolioId and lower(s.name)=lower(:name) and (:excludeId is null or s.id<>:excludeId)") boolean duplicate(UUID portfolioId,String name,UUID excludeId);}
